//! Ed25519 signatures (RFC 8032, pure variant).
//!
//! Extended coordinates with the unified addition formula (complete for a = -1, d non-square),
//! and a double-and-add-always ladder with constant-time selection for secret scalars.
//! Verification is cofactorless (`[S]B == R + [k]A`, as Go's crypto/ed25519 does), rejects
//! non-canonical S (S >= L) and non-canonical point encodings (y >= p).

use crate::bigint::{U256, ED25519_L as L};
use crate::field25519::Fe;
use crate::sha2::Sha512;

// Generated by Python from the curve definition; `tests::constants` re-derives them.
const D: [u8; 32] = [163, 120, 89, 19, 202, 77, 235, 117, 171, 216, 65, 65, 77, 10, 112, 0, 152, 232, 121, 119, 121, 64, 199, 140, 115, 254, 111, 43, 238, 108, 3, 82];
const D2: [u8; 32] = [89, 241, 178, 38, 148, 155, 214, 235, 86, 177, 131, 130, 154, 20, 224, 0, 48, 209, 243, 238, 242, 128, 142, 25, 231, 252, 223, 86, 220, 217, 6, 36];
const SQRT_M1: [u8; 32] = [176, 160, 14, 74, 39, 27, 238, 196, 120, 228, 47, 173, 6, 24, 67, 47, 167, 215, 251, 61, 153, 0, 77, 43, 11, 223, 193, 79, 128, 36, 131, 43];
const BX: [u8; 32] = [26, 213, 37, 143, 96, 45, 86, 201, 178, 167, 37, 149, 96, 199, 44, 105, 92, 220, 214, 253, 49, 226, 164, 192, 254, 83, 110, 205, 211, 54, 105, 33];
const BY: [u8; 32] = [88, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102, 102];

#[derive(Clone, Copy)]
struct Point {
    x: Fe,
    y: Fe,
    z: Fe,
    t: Fe,
}

impl Point {
    fn identity() -> Point {
        Point { x: Fe::ZERO, y: Fe::ONE, z: Fe::ONE, t: Fe::ZERO }
    }

    fn base() -> Point {
        let (x, y) = (Fe::from_bytes(&BX), Fe::from_bytes(&BY));
        Point { x, y, z: Fe::ONE, t: x.mul(&y) }
    }

    /// add-2008-hwcd-3 (complete for this curve; also used for doubling).
    fn add(&self, o: &Point) -> Point {
        let d2 = Fe::from_bytes(&D2);
        let a = self.y.sub(&self.x).mul(&o.y.sub(&o.x));
        let b = self.y.add(&self.x).mul(&o.y.add(&o.x));
        let c = self.t.mul(&d2).mul(&o.t);
        let d = self.z.add(&self.z).mul(&o.z);
        let (e, f, g, h) = (b.sub(&a), d.sub(&c), d.add(&c), b.add(&a));
        Point { x: e.mul(&f), y: g.mul(&h), z: f.mul(&g), t: e.mul(&h) }
    }

    fn select(a: &Point, b: &Point, choose: u64) -> Point {
        Point { x: Fe::select(&a.x, &b.x, choose), y: Fe::select(&a.y, &b.y, choose), z: Fe::select(&a.z, &b.z, choose), t: Fe::select(&a.t, &b.t, choose) }
    }

    /// k * self for a little-endian 256-bit scalar, constant-time in k.
    fn mul(&self, k: &[u8; 32]) -> Point {
        let mut r = Point::identity();
        for i in (0..256).rev() {
            r = r.add(&r);
            let t = r.add(self);
            r = Point::select(&r, &t, ((k[i >> 3] >> (i & 7)) & 1) as u64);
        }
        r
    }

    fn encode(&self) -> [u8; 32] {
        let zi = self.z.invert();
        let x = self.x.mul(&zi);
        let mut out = self.y.mul(&zi).to_bytes();
        out[31] |= x.is_negative() << 7;
        out
    }

    fn decode(b: &[u8; 32]) -> Option<Point> {
        let sign = b[31] >> 7;
        let mut yb = *b;
        yb[31] &= 0x7f;
        let y = Fe::from_bytes(&yb);
        if y.to_bytes() != yb {
            return None; // y >= p: non-canonical
        }
        // x^2 = u / v with u = y^2 - 1, v = d y^2 + 1; x = u v^3 (u v^7)^((p-5)/8)
        let yy = y.square();
        let u = yy.sub(&Fe::ONE);
        let v = Fe::from_bytes(&D).mul(&yy).add(&Fe::ONE);
        let v3 = v.square().mul(&v);
        let v7 = v3.square().mul(&v);
        let mut x = u.mul(&v3).mul(&u.mul(&v7).pow_p58());
        let vxx = v.mul(&x.square());
        if !vxx.ct_eq(&u) {
            if !vxx.ct_eq(&u.neg()) {
                return None;
            }
            x = x.mul(&Fe::from_bytes(&SQRT_M1));
        }
        if x.is_zero() && sign == 1 {
            return None;
        }
        if x.is_negative() != sign {
            x = x.neg();
        }
        Some(Point { x, y, z: Fe::ONE, t: x.mul(&y) })
    }

    fn ct_eq(&self, o: &Point) -> bool {
        // X1/Z1 == X2/Z2 and Y1/Z1 == Y2/Z2, without inversions.
        self.x.mul(&o.z).ct_eq(&o.x.mul(&self.z)) && self.y.mul(&o.z).ct_eq(&o.y.mul(&self.z))
    }
}

fn sha512_parts(parts: &[&[u8]]) -> [u8; 64] {
    let mut h = Sha512::new();
    for p in parts {
        h.update(p);
    }
    h.finalize()
}

/// H(...) mod L as a little-endian scalar.
fn hash_scalar(parts: &[&[u8]]) -> U256 {
    let mut h = sha512_parts(parts);
    let s = L.reduce_wide_le(&h);
    crate::wipe(&mut h);
    s
}

/// A signing key: the 32-byte seed plus its expansion.
pub struct SigningKey {
    seed: [u8; 32],
    scalar: [u8; 32],
    prefix: [u8; 32],
    public: [u8; 32],
}

impl SigningKey {
    pub fn from_seed(seed: &[u8; 32]) -> SigningKey {
        let mut h = sha512_parts(&[seed]);
        let mut scalar: [u8; 32] = h[..32].try_into().unwrap();
        scalar[0] &= 248;
        scalar[31] &= 127;
        scalar[31] |= 64;
        let prefix = h[32..].try_into().unwrap();
        crate::wipe(&mut h);
        let public = Point::base().mul(&scalar).encode();
        SigningKey { seed: *seed, scalar, prefix, public }
    }

    pub fn seed(&self) -> &[u8; 32] {
        &self.seed
    }

    pub fn public_key(&self) -> [u8; 32] {
        self.public
    }

    pub fn sign(&self, msg: &[u8]) -> [u8; 64] {
        let r = hash_scalar(&[&self.prefix, msg]);
        let big_r = Point::base().mul(&r.to_le_bytes()).encode();
        let k = hash_scalar(&[&big_r, &self.public, msg]);
        // S = r + k * a mod L
        let a = L.reduce(&U256::from_le_bytes(&self.scalar));
        let ka = L.from_mont(&L.mul(&L.to_mont(&k), &L.to_mont(&a)));
        let s = L.add(&r, &ka);
        let mut sig = [0u8; 64];
        sig[..32].copy_from_slice(&big_r);
        sig[32..].copy_from_slice(&s.to_le_bytes());
        sig
    }
}

impl Drop for SigningKey {
    fn drop(&mut self) {
        crate::wipe(&mut self.seed);
        crate::wipe(&mut self.scalar);
        crate::wipe(&mut self.prefix);
    }
}

pub fn verify(public: &[u8; 32], msg: &[u8], sig: &[u8; 64]) -> bool {
    let Some(a) = Point::decode(public) else { return false };
    let r_bytes: [u8; 32] = sig[..32].try_into().unwrap();
    let Some(r) = Point::decode(&r_bytes) else { return false };
    let s = U256::from_le_bytes(sig[32..].try_into().unwrap());
    if !s.ct_lt(&L.m) {
        return false;
    }
    let k = hash_scalar(&[&r_bytes, public, msg]);
    let lhs = Point::base().mul(&s.to_le_bytes());
    let rhs = r.add(&a.mul(&k.to_le_bytes()));
    lhs.ct_eq(&rhs)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn constants() {
        let d = Fe::ZERO.sub(&Fe::from_bytes(&le(121665))).mul(&Fe::from_bytes(&le(121666)).invert());
        assert!(d.ct_eq(&Fe::from_bytes(&D)));
        assert!(d.add(&d).ct_eq(&Fe::from_bytes(&D2)));
        let i = Fe::from_bytes(&SQRT_M1);
        assert!(i.square().ct_eq(&Fe::ONE.neg()));
        // base point: y = 4/5 and on the curve
        let y = Fe::from_bytes(&le(4)).mul(&Fe::from_bytes(&le(5)).invert());
        assert!(y.ct_eq(&Fe::from_bytes(&BY)));
        assert_eq!(Point::decode(&Point::base().encode()).unwrap().encode(), Point::base().encode());
    }

    fn le(v: u32) -> [u8; 32] {
        let mut b = [0u8; 32];
        b[..4].copy_from_slice(&v.to_le_bytes());
        b
    }
}
